#ifndef XMLSCHEMA_CDR_TYPES_HPP
#define XMLSCHEMA_CDR_TYPES_HPP

#include "ace/CDR_Stream.h"
#include "ace/XML_Utils/XMLSchema/Types.hpp"

/*
 * Generic stream interfaces for (de)marshaling XML types generated by XSC.
 * ACE CDR streams provide reusable encoding using the Common Data
 * Representation format. The argument traits provide CORBA-like parameter
 * passing semantics, primarily for reference types.
 */
namespace XMLSchema
{
  using CDR_OutputStream = ACE_OutputCDR;
  using CDR_InputStream = ACE_InputCDR;

  template <typename T>
  struct cdr_arg_traits
  {
    using in_type = T const&;
    using out_type = T&;
    using ret_type = T;
    using inout_type = T*&;
  };
}

template <typename T>
bool
operator<< (XMLSchema::CDR_OutputStream& stream,
            XMLSchema::string<T> const& element)
{
  return stream << element.c_str ();
}

template <typename T>
bool
operator<< (XMLSchema::CDR_OutputStream& stream,
            XMLSchema::IDREF<T> const& element)
{
  return stream << element.id ().c_str ();
}

template <typename T>
bool
operator<< (XMLSchema::CDR_OutputStream& stream, XMLSchema::ID<T> const& element)
{
  return stream << element.c_str ();
}

#endif // XMLSCHEMA_CDR_TYPES_HPP
